import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from 'react-router-dom'; // Assuming you use react-router
import "./RiverDashboard.css";

// The endpoint provided in your views.py
const DEBUG_API = "http://127.0.0.1:8000/api/weather/debug-read-s3";

const RiverDashboard = () => {
  const navigate = useNavigate();
  
  // --- STATE MANAGEMENT ---
  const [forecastData, setForecastData] = useState([]);
  const [limeData, setLimeData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [lastUpdated, setLastUpdated] = useState("");
  
  // Clock State for Header
  const [currentTime, setCurrentTime] = useState(new Date());

  // --- HELPERS ---
  const getStatus = (level) => {
    const val = parseFloat(level);
    if (val < 5.5) return { label: "Normal", class: "status-normal", color: "#10b981" }; // Modern Green
    if (val < 6.0) return { label: "Caution", class: "status-caution", color: "#f59e0b" }; // Modern Amber
    return { label: "Warning", class: "status-critical", color: "#ef4444" }; // Modern Red
  };

  // --- EFFECTS ---
  
  // 1. Clock Timer
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // 2. Data Fetching
  useEffect(() => {
    const fetchForecast = async () => {
      try {
        const response = await axios.get(DEBUG_API, { params: { file: "forecast_output.csv" } });
        if (response.data.status === "success") {
          const rawLines = response.data.preview;
          const parsedData = rawLines.slice(1).map((line) => {
              const cols = line.split(",");
              const level = cols[cols.length - 1]?.trim();
              return { level: parseFloat(level).toFixed(2), status: getStatus(level) };
            }).filter((item) => !isNaN(item.level));
          setForecastData(parsedData);
          
          const now = new Date();
          setLastUpdated(now.toLocaleTimeString("en-US", {hour: '2-digit', minute:'2-digit'}));
        }
      } catch (err) {
        console.error("Forecast API error:", err);
        setError("Failed to fetch forecast data");
      }
    };

    const fetchLimeInsights = async () => {
      try {
        const response = await axios.get(DEBUG_API, { params: { file: "lime_short_sentences_and_labels.txt" } });
        if (response.data.status === "success") {
          setLimeData(response.data.preview);
        }
      } catch (err) {
        console.error("LIME API error:", err);
      }
    };

    const loadAllData = async () => {
      setLoading(true);
      await Promise.all([fetchForecast(), fetchLimeInsights()]);
      setLoading(false);
    };

    loadAllData();
  }, []);

  // --- RENDER HELPERS ---
  
  // Safe access for display
  const nextHour = forecastData[0] || { level: "--", status: getStatus(0) };
  const currentLevel = (parseFloat(nextHour.level) - 0.17).toFixed(2);
  const currentStatus = getStatus(currentLevel); // Calculate status for current level too

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Loading Environmental Models...</p></div>;
  if (error && forecastData.length === 0) return <div className="rd-error"><h3>System Offline</h3><p>{error}</p></div>;

  return (
    <div className="rd-container">
      
      {/* --- GOVT HEADER (Matched Style) --- */}
      <header className="rd-gov-header">
        <div className="rd-header-top">
          <div className="rd-wrapper rd-flex-between">
            <div className="rd-gov-links">
              <a href="https://www.india.gov.in" target="_blank" rel="noopener noreferrer">Govt. of India</a>
              <span className="rd-divider">|</span>
              <a href="https://moes.gov.in" target="_blank" rel="noopener noreferrer">Ministry of Earth Sciences</a>
            </div>
            <div className="rd-time">
              {currentTime.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'medium', timeStyle: 'short' })}
            </div>
          </div>
        </div>
        
        <div className="rd-header-main">
          <div className="rd-wrapper rd-flex-center">
            <div className="rd-logo-circle">
              <i className="fas fa-water"></i>
            </div>
            <div className="rd-site-title">
              <h1>Periyar River Flood Monitoring</h1>
              <p>Adi Shankara Institute of Engineering & Technology</p>
            </div>
          </div>
        </div>
      </header>

      {/* --- NAVIGATION --- */}
      <nav className="rd-nav">
        <div className="rd-wrapper">
          <ul>
            <li><a href="/" onClick={(e) => { e.preventDefault(); navigate('/'); }}>Home</a></li>
            <li><a href="#" className="active">River Forecast</a></li>
            <li><a href="#" onClick={(e) => { e.preventDefault(); navigate('/weather-map'); }}>Weather Map</a></li>
            <li><a href="#contact">Contact</a></li>
          </ul>
        </div>
      </nav>

      {/* --- MAIN DASHBOARD CONTENT --- */}
      <main className="rd-main-content rd-wrapper">
        
        {/* Top Control Bar */}
        <div className="rd-control-bar">
          <div className="rd-system-status">
            <span className="rd-status-dot pulse"></span>
            System Live & Monitoring
          </div>
          <div className="rd-last-update">
            Last Model Run: <strong>{lastUpdated}</strong>
          </div>
        </div>

        {/* Global Alert Banner (Dynamic) */}
        <div className={`rd-banner ${nextHour.status.class}`}>
          <div className="rd-banner-icon"><i className="fas fa-bullhorn"></i></div>
          <div className="rd-banner-text">
             <strong>Current Status: {nextHour.status.label.toUpperCase()}</strong> — 
             Based on real-time sensor data and AI predictive modeling for the Kalady region.
          </div>
        </div>

        {/* Key Metrics Grid */}
        <div className="rd-grid-hero">
          
          {/* Card 1: Current Level */}
          <div className="rd-card rd-card-highlight">
            <div className="rd-card-header">
              <span>Current Water Level</span>
              <i className="fas fa-ruler-vertical"></i>
            </div>
            <div className="rd-big-metric">
              {currentLevel} <span className="unit">meters</span>
            </div>
            <div className="rd-badge" style={{backgroundColor: currentStatus.color}}>
              {currentStatus.label}
            </div>
            <div className="rd-subtext">Sensor ID: WL-2024-KLD</div>
          </div>

          {/* Card 2: Next Hour Prediction */}
          <div className="rd-card">
            <div className="rd-card-header">
              <span>1-Hour Forecast</span>
              <i className="fas fa-clock"></i>
            </div>
            <div className="rd-big-metric" style={{color: nextHour.status.color}}>
              {nextHour.level} <span className="unit">meters</span>
            </div>
            <div className="rd-subtext">
              AI Confidence: 98.5%
            </div>
             <div className="rd-trend">
                {parseFloat(nextHour.level) > parseFloat(currentLevel) 
                  ? <span><i className="fas fa-arrow-up"></i> Rising</span> 
                  : <span><i className="fas fa-arrow-down"></i> Falling</span>
                }
             </div>
          </div>
        </div>

        {/* 6 Hour Forecast Grid */}
        <section className="rd-section">
          <h2 className="rd-section-title"><i className="fas fa-chart-bar"></i> 6-Hour Water Level Projection</h2>
          <div className="rd-forecast-strip">
            {forecastData.slice(0, 6).map((data, index) => (
              <div key={index} className="rd-forecast-mini-card">
                <div className="time">H+{index + 1}</div>
                <div className="value">{data.level}m</div>
                <div className="status" style={{color: data.status.color}}>{data.status.label}</div>
                <div className="bar" style={{height: `${(data.level/8)*100}%`, backgroundColor: data.status.color}}></div>
              </div>
            ))}
          </div>
        </section>

        {/* Explainable AI Insights (LIME) */}
        <section className="rd-section">
          <h2 className="rd-section-title"><i className="fas fa-brain"></i> Explainable AI Insights (LIME)</h2>
          <div className="rd-lime-container">
            {limeData.length > 0 ? (
              limeData.slice(0, 6).map((line, index) => {
                const forecastItem = forecastData[index];
                const statusColor = forecastItem ? forecastItem.status.color : "#3b82f6";
                const statusLabel = forecastItem ? forecastItem.status.label : "Info";

                return (
                  <div key={index} className="rd-lime-row" style={{borderLeftColor: statusColor}}>
                    <div className="rd-lime-meta">
                      <span className="hour-pill">H+{index + 1}</span>
                      <span className="status-pill" style={{backgroundColor: statusColor}}>{statusLabel}</span>
                    </div>
                    <div className="rd-lime-content">
                      <p>{line}</p>
                    </div>
                  </div>
                );
              })
            ) : (
               <div className="rd-empty-state">No AI insights available at this moment.</div>
            )}
          </div>
        </section>

      </main>

      {/* --- FOOTER --- */}
      <footer className="rd-footer">
        <div className="rd-wrapper rd-footer-grid">
          <div>
            <h4>About System</h4>
            <p>Advanced IoT & AI integrated river monitoring system funded by MeitY, Govt of India.</p>
          </div>
          <div>
            <h4>Quick Links</h4>
            <ul>
              <li><a href="/">Home</a></li>
              <li><a href="https://moes.gov.in">Ministry of Earth Sciences</a></li>
              <li><a href="#contact">Emergency Contact</a></li>
            </ul>
          </div>
          <div>
             <h4>Adi Shankara Institute</h4>
             <p>Kalady, Ernakulam, Kerala - 683574</p>
             <p>&copy; {new Date().getFullYear()} Weather Monitoring System</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default RiverDashboard;
